"""Materialize manually scoped Hermes research findings; never imports upstream code."""
import hashlib
import json
from pathlib import Path

BASE = Path(__file__).resolve().parent
SOURCE = BASE.parent / "_sources" / "hermes"
COMMIT = "e6f57427c198cfd96854522b7a9159eb007e13c2"
FINDINGS = []


def finding(id, statement, path, first, last, limits, status="code-traced", related_docs=None):
    lines = (SOURCE / path).read_text(encoding="utf-8").splitlines()
    # A range ending beyond EOF is an authoring error, never silently clamped.
    assert 1 <= first <= last <= len(lines), (id, path, len(lines))
    excerpt = "\n".join(lines[first - 1:last])
    FINDINGS.append(dict(id=id, statement=statement, status=status, source_path=path,
                         line_start=first, line_end=last, commit=COMMIT, limits=limits,
                         source_url=f"https://github.com/NousResearch/hermes-agent/blob/{COMMIT}/{path}#L{first}-L{last}",
                         selected_lines_sha256=hashlib.sha256(excerpt.encode()).hexdigest(),
                         related_docs=related_docs or []))


